//
// NOVEL — not generated by CLI Printing Press. See
// .printing-press-patches/garmin-loopback-sso-auth.json.
//
// Step 6 of the login writes two files: the token chain (a secret, through the
// generated SaveTokens) and the identity sidecar (not a secret, beside
// config.toml). Only one order is honest for a login. Writing the credentials
// first means a sidecar failure reports a failed login over credentials that
// have already changed — the caller is told nothing was stored, and the next
// command uses the new token with no record of which account it belongs to. So
// the sidecar goes first and the credential write is the commit point: a
// sidecar failure leaves the credentials untouched, and a credential failure
// puts the sidecar back.
//
// Two induction techniques are in play. A regular file standing where a
// directory must be fails the credential write, and a directory standing at
// the sidecar path fails the prior-bytes READ (EISDIR, not ENOENT) — not the
// sidecar write, which is never reached. Both fail for root too, so those
// cases need no os.Geteuid() guard and no Windows skip. The read guard
// returns before SaveTokens in either write order, so it pins nothing about
// the order; the two cases that do are the ones driven through
// garminSaveIdentityForPersist. The first fails that write with a synthetic
// error, which bites on every platform and for root, so it needs no skip; only
// the second, which also makes the config dir read-only, carries the root and
// Windows skips.

package cli

import (
	"errors"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
	"time"
)

// newPersistLoginHome builds a home with a plain config.toml and returns its
// resolved config path. GARMIN_HOME moves config, data, state and cache under
// one temp root, so nothing here can reach a real home.
func newPersistLoginHome(t *testing.T) string {
	t.Helper()
	home := t.TempDir()
	t.Setenv("GARMIN_HOME", home)
	configDir := filepath.Join(home, "config")
	if err := os.MkdirAll(configDir, 0o700); err != nil {
		t.Fatalf("make config dir: %v", err)
	}
	configPath := filepath.Join(configDir, "config.toml")
	if err := os.WriteFile(configPath, []byte("base_url = 'https://connectapi.garmin.com'\n"), 0o600); err != nil {
		t.Fatalf("write config: %v", err)
	}
	return configPath
}

// persistLoginFixtureTokens is a synthetic chain. Nothing here reaches Garmin:
// the strings are never sent anywhere, they are only written and read back.
func persistLoginFixtureTokens() *garminTokens {
	return &garminTokens{
		AccessToken:   "synthetic-access-not-a-real-token",
		RefreshToken:  "synthetic-refresh-not-a-real-token",
		ClientID:      "GARMIN_TEST_CLIENT",
		TokenExpiry:   time.Now().Add(20 * time.Hour).UTC().Truncate(time.Second),
		RefreshExpiry: time.Now().Add(720 * time.Hour).UTC().Truncate(time.Second),
	}
}

func persistLoginFixtureIdentity(email string) *garminIdentity {
	return &garminIdentity{
		Email:         email,
		GarminGUID:    "aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee",
		Domain:        garminDomainGlobal,
		ClientID:      "GARMIN_TEST_CLIENT",
		RefreshExpiry: time.Now().Add(720 * time.Hour).UTC().Truncate(time.Second),
		AssertedAt:    time.Now().UTC().Truncate(time.Second),
	}
}

// credentialsFileForHome is where SaveTokens actually lands the secret:
// cliutil.SaveCredentials resolves through DataDir(), which under GARMIN_HOME
// is <home>/data — a different directory from the config dir the sidecar and
// config.toml share.
func credentialsFileForHome(t *testing.T, configPath string) string {
	t.Helper()
	home := filepath.Dir(filepath.Dir(configPath))
	return filepath.Join(home, "data", "credentials.toml")
}

// blockDataDir points the data kind at a path whose parent is a regular file,
// so the credential write fails while the config dir stays perfectly writable.
func blockDataDir(t *testing.T, configPath string) {
	t.Helper()
	home := filepath.Dir(filepath.Dir(configPath))
	blocker := filepath.Join(home, "blocker")
	if err := os.WriteFile(blocker, []byte("not a directory"), 0o600); err != nil {
		t.Fatalf("write blocker: %v", err)
	}
	t.Setenv("GARMIN_DATA_DIR", filepath.Join(blocker, "data"))
}

// blockSidecar puts a directory where the sidecar file must be, so the
// sidecar's atomic publish fails while everything else stays writable.
func blockSidecar(t *testing.T, configPath string) {
	t.Helper()
	if err := os.MkdirAll(garminIdentityPath(configPath), 0o700); err != nil {
		t.Fatalf("block sidecar path: %v", err)
	}
}

// TestPersistLoginLeavesCredentialsUntouchedWhenThePriorSidecarReadFails is the defect
// case: the command reported a failed login over already-changed credentials.
func TestPersistLoginLeavesCredentialsUntouchedWhenThePriorSidecarReadFails(t *testing.T) {
	configPath := newPersistLoginHome(t)
	credsPath := credentialsFileForHome(t, configPath)
	blockSidecar(t, configPath)

	err := garminPersistLoginResult(configPath, "", persistLoginFixtureTokens(),
		persistLoginFixtureIdentity("placeholder@example.test"))
	if err == nil {
		t.Fatal("the persist reported success although the sidecar could not be written")
	}
	if _, statErr := os.Stat(credsPath); !os.IsNotExist(statErr) {
		data, _ := os.ReadFile(credsPath)
		t.Fatalf("a failed login wrote credentials anyway at %s: %d bytes", credsPath, len(data))
	}
}

// The same case with a credential already on disk: it must come through the
// failed login byte-identical, not half-rewritten.
func TestPersistLoginKeepsPriorCredentialsWhenThePriorSidecarReadFails(t *testing.T) {
	configPath := newPersistLoginHome(t)
	credsPath := credentialsFileForHome(t, configPath)

	// Seed a credential the honest way, then block the sidecar for the retry.
	if err := garminPersistLoginResult(configPath, "", persistLoginFixtureTokens(),
		persistLoginFixtureIdentity("placeholder@example.test")); err != nil {
		t.Fatalf("seeding the first login: %v", err)
	}
	before, err := os.ReadFile(credsPath)
	if err != nil {
		t.Fatalf("reading the seeded credentials: %v", err)
	}
	if err := os.Remove(garminIdentityPath(configPath)); err != nil {
		t.Fatalf("removing the seeded sidecar: %v", err)
	}
	blockSidecar(t, configPath)

	second := persistLoginFixtureTokens()
	second.AccessToken = "synthetic-access-second-not-a-real-token"
	second.RefreshToken = "synthetic-refresh-second-not-a-real-token"
	if err := garminPersistLoginResult(configPath, "", second,
		persistLoginFixtureIdentity("placeholder@example.test")); err == nil {
		t.Fatal("the persist reported success although the sidecar could not be written")
	}
	after, err := os.ReadFile(credsPath)
	if err != nil {
		t.Fatalf("the credentials file is gone after a failed login: %v", err)
	}
	if string(after) != string(before) {
		t.Fatalf("a failed login rewrote the credentials file:\nbefore:\n%s\nafter:\n%s", before, after)
	}
}

// TestPersistLoginRestoresThePriorSidecarWhenTheCredentialWriteFails is the
// other half: the sidecar is written first, so a credential failure has to put
// the previous sidecar back rather than leave the home claiming an account it
// holds no token for.
func TestPersistLoginRestoresThePriorSidecarWhenTheCredentialWriteFails(t *testing.T) {
	configPath := newPersistLoginHome(t)
	if err := garminSaveIdentity(configPath, persistLoginFixtureIdentity("prior@example.test")); err != nil {
		t.Fatalf("seeding the prior sidecar: %v", err)
	}
	before, err := os.ReadFile(garminIdentityPath(configPath))
	if err != nil {
		t.Fatalf("reading the prior sidecar: %v", err)
	}
	blockDataDir(t, configPath)

	if err := garminPersistLoginResult(configPath, "", persistLoginFixtureTokens(),
		persistLoginFixtureIdentity("new@example.test")); err == nil {
		t.Fatal("the persist reported success although the credentials could not be written")
	}
	after, err := os.ReadFile(garminIdentityPath(configPath))
	if err != nil {
		t.Fatalf("the prior sidecar is gone after a failed login: %v", err)
	}
	if string(after) != string(before) {
		t.Fatalf("the prior sidecar was not restored byte-for-byte:\nbefore:\n%s\nafter:\n%s", before, after)
	}
}

// With no prior sidecar there is nothing to restore, so a failed credential
// write must leave none behind: a sidecar with no token names an account this
// home cannot reach.
func TestPersistLoginLeavesNoSidecarWhenTheCredentialWriteFailsAndNoneExisted(t *testing.T) {
	configPath := newPersistLoginHome(t)
	blockDataDir(t, configPath)

	if err := garminPersistLoginResult(configPath, "", persistLoginFixtureTokens(),
		persistLoginFixtureIdentity("placeholder@example.test")); err == nil {
		t.Fatal("the persist reported success although the credentials could not be written")
	}
	if _, err := os.Stat(garminIdentityPath(configPath)); !os.IsNotExist(err) {
		t.Fatalf("a failed login left a sidecar behind: stat err = %v", err)
	}
}

// TestPersistLoginWritesBothOnSuccess is the positive control, and it also
// pins where each file actually lands. The sidecar sits beside config.toml in
// the config dir; the credential lands in the DATA dir, which is a different
// directory — so writing the sidecar first proves the config dir writable, not
// the credential dir.
func TestPersistLoginWritesBothOnSuccess(t *testing.T) {
	configPath := newPersistLoginHome(t)
	id := persistLoginFixtureIdentity("placeholder@example.test")
	if err := garminPersistLoginResult(configPath, "", persistLoginFixtureTokens(), id); err != nil {
		t.Fatalf("a clean login failed: %v", err)
	}

	loaded, err := garminLoadIdentity(configPath)
	if err != nil {
		t.Fatalf("the sidecar does not round-trip: %v", err)
	}
	if loaded.Email != id.Email || loaded.GarminGUID != id.GarminGUID || loaded.ClientID != id.ClientID {
		t.Fatalf("sidecar round-tripped as %#v, want %#v", loaded, id)
	}

	credsPath := credentialsFileForHome(t, configPath)
	creds, err := os.ReadFile(credsPath)
	if err != nil {
		t.Fatalf("no credentials file at %s: %v", credsPath, err)
	}
	if !strings.Contains(string(creds), "synthetic-refresh-not-a-real-token") {
		t.Fatalf("the credentials file does not hold the chain that was saved:\n%s", creds)
	}

	// Evidence for the path claim above rather than a code reading: the
	// credential is NOT beside the config file, and it is NOT in the
	// Dir(config)/data sibling that the explicit --config LOAD path
	// (cliutil.CredentialsFilePathForConfig) would look in.
	if _, err := os.Stat(filepath.Join(filepath.Dir(configPath), "credentials.toml")); !os.IsNotExist(err) {
		t.Fatalf("credentials landed beside config.toml: stat err = %v", err)
	}
	if _, err := os.Stat(filepath.Join(filepath.Dir(configPath), "data", "credentials.toml")); !os.IsNotExist(err) {
		t.Fatalf("credentials landed in the config dir's data sibling: stat err = %v", err)
	}
	if _, err := os.Stat(garminIdentityPath(configPath)); err != nil {
		t.Fatalf("the sidecar is not beside config.toml: %v", err)
	}
}

// TestPersistLoginLeavesCredentialsUntouchedWhenTheSidecarWriteFails is the
// case that actually pins the order. Blocking the sidecar path on disk fails
// the prior-bytes READ, which returns before SaveTokens whichever way round
// the two writes are; only a failure of the WRITE itself tells them apart.
func TestPersistLoginLeavesCredentialsUntouchedWhenTheSidecarWriteFails(t *testing.T) {
	configPath := newPersistLoginHome(t)
	credsPath := credentialsFileForHome(t, configPath)
	if err := garminSaveIdentity(configPath, persistLoginFixtureIdentity("prior@example.test")); err != nil {
		t.Fatalf("seeding the prior sidecar: %v", err)
	}
	before, err := os.ReadFile(garminIdentityPath(configPath))
	if err != nil {
		t.Fatalf("reading the prior sidecar: %v", err)
	}

	restore := garminSaveIdentityForPersist
	t.Cleanup(func() { garminSaveIdentityForPersist = restore })
	garminSaveIdentityForPersist = func(string, *garminIdentity) error {
		return errors.New("synthetic sidecar write failure")
	}

	if err := garminPersistLoginResult(configPath, "", persistLoginFixtureTokens(),
		persistLoginFixtureIdentity("new@example.test")); err == nil {
		t.Fatal("the persist reported success although the sidecar write failed")
	}
	if _, statErr := os.Stat(credsPath); !os.IsNotExist(statErr) {
		data, _ := os.ReadFile(credsPath)
		t.Fatalf("a failed sidecar write let credentials through at %s: %d bytes", credsPath, len(data))
	}
	after, err := os.ReadFile(garminIdentityPath(configPath))
	if err != nil {
		t.Fatalf("the prior sidecar is gone after a failed sidecar write: %v", err)
	}
	if string(after) != string(before) {
		t.Fatalf("the prior sidecar changed after a failed sidecar write:\nbefore:\n%s\nafter:\n%s", before, after)
	}
}

// Only SaveTokens' SECOND write fails here: credentials.toml lands in the data
// dir, config.toml cannot be published into the now read-only config dir. The
// chain on disk is the new one, so the sidecar must NOT be rolled back and the
// error must say the chain changed.
func TestPersistLoginTellsTheTruthWhenOnlyConfigTomlFails(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("directory permissions do not gate a rename on Windows")
	}
	if os.Geteuid() == 0 {
		t.Skip("root ignores the directory mode this case depends on")
	}
	configPath := newPersistLoginHome(t)
	credsPath := credentialsFileForHome(t, configPath)
	configDir := filepath.Dir(configPath)
	if err := garminSaveIdentity(configPath, persistLoginFixtureIdentity("prior@example.test")); err != nil {
		t.Fatalf("seeding the prior sidecar: %v", err)
	}

	restore := garminSaveIdentityForPersist
	t.Cleanup(func() { garminSaveIdentityForPersist = restore })
	garminSaveIdentityForPersist = func(cp string, id *garminIdentity) error {
		if err := garminSaveIdentity(cp, id); err != nil {
			return err
		}
		if err := os.Chmod(configDir, 0o500); err != nil {
			return err
		}
		t.Cleanup(func() { _ = os.Chmod(configDir, 0o700) })
		return nil
	}

	tokens := persistLoginFixtureTokens()
	tokens.RefreshToken = "synthetic-refresh-second-not-a-real-token"
	err := garminPersistLoginResult(configPath, "", tokens, persistLoginFixtureIdentity("new@example.test"))
	if err == nil {
		t.Fatal("the persist reported success although config.toml could not be written")
	}
	creds, readErr := os.ReadFile(credsPath)
	if readErr != nil {
		t.Fatalf("reading credentials: %v", readErr)
	}
	if !strings.Contains(string(creds), "synthetic-refresh-second-not-a-real-token") {
		t.Skip("this platform did not reach SaveTokens' second write; nothing to assert")
	}
	if !strings.Contains(err.Error(), "had already been replaced") {
		t.Fatalf("the credential chain changed but the error does not say so: %v", err)
	}
	sidecar, sidecarErr := os.ReadFile(garminIdentityPath(configPath))
	if sidecarErr != nil {
		t.Fatalf("reading the sidecar: %v", sidecarErr)
	}
	if !strings.Contains(string(sidecar), "new@example.test") {
		t.Fatalf("the sidecar was rolled back to the prior account although the new chain is on disk:\n%s", sidecar)
	}
}
